{
  "name": "post-check-run",
  "$schema": "../../node_modules/nx/schemas/project-schema.json",
  "projectType": "library",
  "root": "packages/post-check-run",
  "sourceRoot": "packages/post-check-run/src",
  "targets": {
    "build": {
      "executor": "@nx/esbuild:esbuild",
      "outputs": ["{options.outputPath}"],
      "options": {
        "main": "packages/post-check-run/src/action.ts",
        "outputPath": "packages/post-check-run/dist",
        "outputFileName": "main.cjs",
        "tsConfig": "packages/post-check-run/tsconfig.json",
        "bundle": true,
        "platform": "node",
        "target": "node20",
        "format": ["cjs"],
        "thirdParty": true
      }
    },
    "build-tests": {
      "_comment": "packages/post-check-run/dist-test/index.cjs is gitignored (see /.gitignore). It is rebuilt on demand before :test runs. Keeping it out of git prevents esbuild's cwd-relative path comment from drifting between local and CI builds.",
      "executor": "nx:run-commands",
      "options": {
        "cwd": "packages/post-check-run",
        "command": "esbuild src/index.ts --bundle --platform=node --target=node20 --format=cjs --outfile=dist-test/index.cjs"
      }
    },
    "test": {
      "executor": "nx:run-commands",
      "dependsOn": ["build-tests"],
      "options": {
        "cwd": "packages/post-check-run",
        "command": "node --test test/*.test.cjs"
      }
    }
  }
}
